241	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
242	    @Override
243	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
244	        Owner owner = this.clinicService.findOwnerById(ownerId);
245	        if (owner == null) {
246	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
247	        }
248	        HttpHeaders headers = new HttpHeaders();
249	        Pet pet = petMapper.toPet(petFieldsDto);
250	        owner.setId(ownerId);
251	        pet.setOwner(owner);
252	        pet.getType().setName(null);
253	        this.clinicService.savePet(pet);
254	        PetDto petDto = petMapper.toPetDto(pet);
255	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
256	            .buildAndExpand(pet.getId()).toUri());
257	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
258	    }
