305	
306	    /**
307	     * Reads the optional {@code Idempotency-Key} header from the current request. The generated
308	     * {@code addOwner} signature carries only the request body, so the header is pulled from the
309	     * request bound to the current thread. Returns the trimmed key, or {@code null} when the header is
310	     * absent or blank (in which case the create proceeds normally, without idempotent replay).
311	     *
312	     * @return the non-blank idempotency key, or {@code null} when none was supplied
313	     */
314	    private String idempotencyKey() {
315	        if (!(RequestContextHolder.getRequestAttributes() instanceof ServletRequestAttributes attributes)) {
316	            return null;
317	        }
318	        String key = attributes.getRequest().getHeader(IDEMPOTENCY_KEY_HEADER);
319	        return isBlank(key) ? null : key.trim();
320	    }
321	
322	    /**
323	     * Rejects an owner whose {@code firstName}, {@code lastName}, {@code address}, {@code city} or
324	     * {@code telephone} is missing (null) or blank (empty or whitespace only). Bean Validation on
325	     * the request body already rejects null and empty values, but permits whitespace-only strings
326	     * for fields without a stricter pattern (e.g. {@code city}, {@code address}); this guard closes
327	     * that gap so every required field must carry a non-blank value.
328	     *
329	     * @param ownerFieldsDto the submitted owner fields
330	     * @throws InvalidOwnerFieldsException if one or more required fields are missing or blank
331	     */
332	    private void rejectBlankOwnerFields(OwnerFieldsDto ownerFieldsDto) {
333	        List<String> missing = new ArrayList<>();
334	        addIfBlank(missing, "firstName", ownerFieldsDto.getFirstName());
335	        addIfBlank(missing, "lastName", ownerFieldsDto.getLastName());
336	        if (isBlank(ownerFieldsDto.getAddressLine1()) && isBlank(ownerFieldsDto.getAddress())) {
337	            missing.add("address");
338	        }
339	        addIfBlank(missing, "city", ownerFieldsDto.getCity());
340	        addIfBlank(missing, "telephone", ownerFieldsDto.getTelephone());
341	        if (!missing.isEmpty()) {
342	            throw new InvalidOwnerFieldsException(missing);
343	        }
344	    }
345	
346	    /**
347	     * Rejects an owner whose supplied {@code postcode} is invalid for its {@code city}. The postcode is
348	     * optional: when absent (null) the owner is accepted unchanged, so the request contract stays
349	     * backward-compatible. When present it must be four digits and, when the city maps to a known region,
350	     * must fall within that region's fixed inclusive range ({@code NSW 2000-2099}, {@code VIC 3000-3099},
351	     * {@code QLD 4000-4099}); a city with no known region accepts any 4-digit postcode. See
352	     * {@link PostcodeValidator}.
353	     *
354	     * @param ownerFieldsDto the submitted owner fields (its {@code city} is non-blank here,
355	     *                       {@link #rejectBlankOwnerFields} having already run)
356	     * @throws InvalidOwnerFieldsException if a postcode is present but not valid for the city
357	     */
358	    private void rejectInvalidPostcode(OwnerFieldsDto ownerFieldsDto) {
359	        if (!PostcodeValidator.isValid(ownerFieldsDto.getCity(), ownerFieldsDto.getPostcode())) {
360	            throw new InvalidOwnerFieldsException(List.of("postcode"));
361	        }
362	    }
363	
364	    private void addIfBlank(List<String> missing, String fieldName, String value) {
365	        if (isBlank(value)) {
366	            missing.add(fieldName);
367	        }
368	    }
369	
370	    private boolean isBlank(String value) {
371	        return value == null || value.isBlank();
372	    }
373	
374	    /**
375	     * Normalizes the submitted address on create to its canonical form (see
376	     * {@link AddressNormalizer#normalize}) and writes it back onto the request so it is the value
377	     * stored and returned, and the form every later address comparison (the required-field check,
378	     * household duplicate detection and the shared household id) is judged on. The structured fields
379	     * are preferred: {@code addressLine1} and the optional {@code addressLine2} are each normalized in
380	     * place, and the flat {@code address} is set to the {@linkplain #composedAddress composed} value
381	     * derived from them when a structured {@code addressLine1} is present, falling back to the
382	     * normalized flat {@code address} otherwise. Any absent field is left absent so
383	     * {@link #rejectBlankOwnerFields} still reports a wholly missing address; a value that is blank
384	     * after normalization likewise reduces to the empty string and is rejected there.
385	     *
386	     * @param ownerFieldsDto the submitted owner fields
387	     */
388	    private void normalizeAddress(OwnerFieldsDto ownerFieldsDto) {
389	        String addressLine1 = AddressNormalizer.normalizeOrNull(ownerFieldsDto.getAddressLine1());
390	        String addressLine2 = AddressNormalizer.normalizeOrNull(ownerFieldsDto.getAddressLine2());
391	        String flatAddress = AddressNormalizer.normalizeOrNull(ownerFieldsDto.getAddress());
392	        ownerFieldsDto.setAddressLine1(addressLine1);
393	        ownerFieldsDto.setAddressLine2(addressLine2);
394	        ownerFieldsDto.setAddress(composedAddress(addressLine1, addressLine2, flatAddress));
395	    }
396	
397	    /**
398	     * Composes the flat {@code address} an owner should carry from its (already normalized) address
399	     * fields, preferring the structured form. When a non-blank {@code addressLine1} is present the
400	     * composed address is {@code addressLine1}, with a single space and {@code addressLine2} appended
401	     * when {@code addressLine2} is present; otherwise the flat {@code address} is used unchanged. This
402	     * is the single value every later reader of the address (the required-field check, household
403	     * duplicate detection and the shared household id) is judged on.
404	     *
405	     * @param addressLine1 the normalized first address line, or {@code null}/blank when absent
406	     * @param addressLine2 the normalized second address line, or {@code null}/blank when absent
407	     * @param flatAddress  the normalized flat address, or {@code null}/blank when absent
408	     * @return the composed flat address, or {@code null} when no address form was supplied
409	     */
410	    private String composedAddress(String addressLine1, String addressLine2, String flatAddress) {
411	        if (isBlank(addressLine1)) {
412	            return flatAddress;
413	        }
414	        if (isBlank(addressLine2)) {
415	            return addressLine1;
416	        }
417	        return addressLine1 + " " + addressLine2;
418	    }
419	
420	    /**
421	     * Normalizes the submitted {@code telephone} on create to its canonical form (see
422	     * {@link TelephoneNormalizer#normalize}) and writes it back onto the request so it is the value
423	     * stored and returned. Any input that does not reduce to a valid telephone is rejected with a
424	     * {@code 400 Bad Request}.
425	     *
426	     * @param ownerFieldsDto the submitted owner fields (its {@code telephone} is non-blank here,
427	     *                       {@link #rejectBlankOwnerFields} having already run)
428	     * @throws InvalidOwnerFieldsException if the telephone cannot be normalized to a valid value
429	     */
430	    private void normalizeTelephone(OwnerFieldsDto ownerFieldsDto) {
431	        String normalized = TelephoneNormalizer.normalize(ownerFieldsDto.getTelephone())
432	            .orElseThrow(() -> new InvalidOwnerFieldsException(List.of("telephone")));
433	        ownerFieldsDto.setTelephone(normalized);
434	    }
435	
436	    /**
437	     * Normalizes an optionally-supplied {@code email}. When absent (null) or blank the field is left
438	     * untouched (email is optional). When present it is reduced to its canonical form (see
439	     * {@link EmailNormalizer#normalize}) and written back so it is the value stored and returned. Any
440	     * present-but-invalid address is rejected with a {@code 400 Bad Request}.
441	     *
442	     * @param ownerFieldsDto the submitted owner fields
443	     * @throws InvalidOwnerFieldsException if the email is present but not a syntactically valid address,
444	     *                                     or its domain is on the disposable-domain blocklist
445	     */
446	    private void normalizeEmail(OwnerFieldsDto ownerFieldsDto) {
447	        String email = ownerFieldsDto.getEmail();
448	        if (email == null || email.isBlank()) {
449	            return;
450	        }
451	        String normalized = EmailNormalizer.normalize(email)
452	            .orElseThrow(() -> new InvalidOwnerFieldsException(List.of("email")));
453	        if (EmailNormalizer.hasDisposableDomain(normalized)) {
454	            throw new InvalidOwnerFieldsException(List.of("email"));
455	        }
456	        ownerFieldsDto.setEmail(normalized);
457	    }
458	
459	    /**
460	     * Rejects creating an owner whose derived identity collides with an existing owner. All owner
461	     * duplicate detection is now expressed through the single derived {@code identityKey}
462	     * ({@code normalizedTelephone + '|' + email + '|' + householdId}, see {@link OwnerIdentity}),
463	     * which replaces the previously separate telephone, email and household checks. Two owners denote
464	     * the same person when their identities collide on the telephone - the identity's distinguishing
465	     * component - so a create is rejected as a {@code 409 Conflict} when another owner already carries
466	     * the same normalized telephone. Because the telephone is part of the identity, two members of the
467	     * same household with different telephones have different identities and are both allowed; an email
468	     * or a household on its own no longer makes a duplicate.
469	     *
470	     * @param ownerFieldsDto the submitted owner fields, with telephone and email already normalized
471	     *                       ({@link #normalizeTelephone}, {@link #normalizeEmail})
472	     * @param householdId    the household id derived for the owner being created (see
473	     *                       {@link HouseholdNormalizer#toHouseholdId})
474	     * @throws DuplicateOwnerIdentityException if another owner already carries the same identity
475	     */
476	    private void rejectDuplicateIdentity(OwnerFieldsDto ownerFieldsDto, String householdId) {
477	        String identityKey = OwnerIdentity.identityKey(
478	            ownerFieldsDto.getTelephone(), ownerFieldsDto.getEmail(), householdId);
479	        String telephoneKey = TelephoneNormalizer.toComparisonKey(ownerFieldsDto.getTelephone());
480	        boolean inUse = this.clinicService.findAllOwners().stream()
481	            .filter(existing -> !existing.isDeleted())
482	            .map(Owner::getTelephone)
483	            .filter(Objects::nonNull)
484	            .map(TelephoneNormalizer::toComparisonKey)
485	            .anyMatch(telephoneKey::equals);
486	        if (inUse) {
487	            throw new DuplicateOwnerIdentityException(identityKey);
488	        }
489	    }
490	
491	    /**
492	     * Counts the existing owners (before this create) whose {@code firstName} and {@code lastName}
493	     * both match the submitted values, compared case-insensitively. The count reflects only owners
494	     * already persisted at the time of the create, so the owner being created is never included.
495	     *
496	     * @param firstName the submitted first name (non-blank here, {@link #rejectBlankOwnerFields}
497	     *                  having already run)
498	     * @param lastName  the submitted last name (non-blank here)
499	     * @return the number of existing owners sharing the same first and last name
500	     */
501	    private int countNamesakes(String firstName, String lastName) {
502	        return (int) this.clinicService.findAllOwners().stream()
503	            .filter(owner -> firstName.equalsIgnoreCase(owner.getFirstName())
504	                && lastName.equalsIgnoreCase(owner.getLastName()))
505	            .count();
506	    }
507	
508	    /**
509	     * Counts the existing owners (before this create) belonging to the given household, i.e. those
510	     * whose stored {@code householdId} equals the value derived for the owner being created. The
511	     * count reflects only owners already persisted at the time of the create, so the owner being
512	     * created is never included; callers add one to obtain the household size after this create.
513	     *
514	     * @param householdId the household identifier derived for the owner being created (see
515	     *                    {@link HouseholdNormalizer#toHouseholdId})
516	     * @return the number of existing owners already sharing that household
517	     */
518	    private int countHouseholdMembers(String householdId) {
519	        if (householdId == null) {
520	            return 0;
521	        }
522	        return (int) this.clinicService.findAllOwners().stream()
523	            .map(Owner::getHouseholdId)
524	            .filter(householdId::equals)
525	            .count();
526	    }
527	
528	    /**
529	     * Derives the address an owner should carry from its submitted fields. The update path stamps an
530	     * owner with an address taken from the request, so routing that through this single method keeps the
531	     * derivation of "the owner's address" in one place, mirroring {@link #householdIdFor} for the
532	     * household id.
533	     *
534	     * @param ownerFieldsDto the submitted owner fields
535	     * @return the address to store on the owner
536	     */
537	    private String addressFor(OwnerFieldsDto ownerFieldsDto) {
538	        return ownerFieldsDto.getAddress();
539	    }
540	
541	    /**
542	     * Derives the household id an owner should carry from its submitted fields (see
543	     * {@link HouseholdNormalizer#toHouseholdId}). Both create and update stamp an owner with a
544	     * household id, so routing them through this single method keeps them agreed on which of the
545	     * owner's fields key the household.
546	     *
547	     * @param ownerFieldsDto the submitted owner fields (its identifying fields are non-blank here,
548	     *                       {@link #rejectBlankOwnerFields} having already run on create)
549	     * @return the owner's household id
550	     */
551	    private String householdIdFor(OwnerFieldsDto ownerFieldsDto) {
552	        return HouseholdNormalizer.toHouseholdId(
553	            ownerFieldsDto.getLastName(), ownerFieldsDto.getPostcode());
554	    }
555	
556	    /**
557	     * Rejects creating an owner that would join an existing household without declaring itself a
558	     * member. The household is keyed on (last name, postcode) through the derived {@code householdId}
559	     * (see {@link HouseholdNormalizer#toHouseholdId}), so a second owner sharing an existing owner's
560	     * last name and postcode denotes the same household. Such a create is reported as a {@code 409
561	     * Conflict} unless it opts in with {@code sharesHousehold}, in which case it is accepted as a
562	     * declared household member. Only owners already persisted (before this create) are considered.
563	     *
564	     * @param householdId     the household id derived for the owner being created
565	     * @param sharesHousehold whether the request opted in to sharing a household
566	     * @throws DuplicateOwnerHouseholdException if the household already exists and the request did not
567	     *                                          opt in with {@code sharesHousehold}
568	     */
569	    private void rejectHouseholdDuplicate(String householdId, boolean sharesHousehold) {
570	        if (sharesHousehold || householdId == null) {
571	            return;
572	        }
573	        boolean householdExists = this.clinicService.findAllOwners().stream()
574	            .filter(existing -> !existing.isDeleted())
575	            .map(Owner::getHouseholdId)
576	            .anyMatch(householdId::equals);
577	        if (householdExists) {
578	            throw new DuplicateOwnerHouseholdException(householdId);
579	        }
580	    }
581	
582	    /**
583	     * Finds an existing owner that the owner being created soft-matches on, or {@code null} when there
584	     * is none. The create has already cleared the hard-duplicate identity check
585	     * ({@link #rejectDuplicateIdentity}), so it is not an exact match of any existing owner; it is a
586	     * <em>possible</em> duplicate when it nevertheless shares an existing owner's {@code lastName}
587	     * (compared case-insensitively) and {@code postcode} while carrying a different normalized
588	     * telephone. The oldest such owner (the earliest persisted) is returned so the flag points at the
589	     * original record; owners with no postcode never match, since a shared postcode is required.
590	     *
591	     * @param owner the owner being created, with telephone already normalized and lastName/postcode set
592	     * @return the id of the matching existing owner, or {@code null} when the owner is not a possible
593	     *         duplicate
594	     */
595	    private Integer findPossibleDuplicate(Owner owner) {
596	        String postcode = owner.getPostcode();
597	        if (postcode == null) {
598	            return null;
599	        }
600	        String telephoneKey = TelephoneNormalizer.toComparisonKey(owner.getTelephone());
601	        return this.clinicService.findAllOwners().stream()
602	            .filter(existing -> !existing.isDeleted())
603	            .filter(existing -> owner.getLastName().equalsIgnoreCase(existing.getLastName()))
604	            .filter(existing -> postcode.equals(existing.getPostcode()))
605	            .filter(existing -> existing.getTelephone() != null
606	                && !telephoneKey.equals(TelephoneNormalizer.toComparisonKey(existing.getTelephone())))
607	            .map(Owner::getId)
608	            .filter(Objects::nonNull)
609	            .min(Integer::compareTo)
610	            .orElse(null);
611	    }
612	
613	    /**
614	     * Records on the owner being created whether it is a possible (soft) duplicate of an existing
615	     * owner. The match itself is decided by {@link #findPossibleDuplicate}; this method reflects its
616	     * result into the two stored fields, so the interpretation of "is a possible duplicate" lives in
617	     * one place: {@code possibleDuplicateOf} holds the matched owner's id (or {@code null} when there
618	     * is none) and {@code possibleDuplicate} is {@code true} exactly when a match was found. An owner
619	     * that opted in with {@code sharesHousehold} is a declared household member, not a suspected
620	     * duplicate, so it is never flagged.
621	     *
622	     * @param owner           the owner being created, with telephone already normalized and
623	     *                        lastName/postcode set
624	     * @param sharesHousehold whether the request opted in to sharing a household
625	     */
626	    private void markPossibleDuplicate(Owner owner, boolean sharesHousehold) {
627	        Integer possibleDuplicateOf = sharesHousehold ? null : findPossibleDuplicate(owner);
628	        owner.setPossibleDuplicate(possibleDuplicateOf != null);
629	        owner.setPossibleDuplicateOf(possibleDuplicateOf);
630	    }
631	
632	    /**
633	     * Rejects creating an owner whose city already holds {@link #MAX_OWNERS_PER_CITY} or more owners.
634	     * The submitted city is compared case-insensitively against every existing owner's stored city; a
635	     * city that is already at (or over) capacity is reported as a {@code 409 Conflict}.
636	     *
637	     * @param city the submitted city (non-blank here, {@link #rejectBlankOwnerFields} having already
638	     *             run)
639	     * @throws OwnerCityAtCapacityException if the city already contains the maximum number of owners
640	     */
641	    private void rejectCityAtCapacity(String city) {
642	        long ownersInCity = this.clinicService.findAllOwners().stream()
643	            .map(Owner::getCity)
644	            .filter(Objects::nonNull)
645	            .filter(city::equalsIgnoreCase)
646	            .count();
647	        if (ownersInCity >= MAX_OWNERS_PER_CITY) {
648	            throw new OwnerCityAtCapacityException(city);
649	        }
650	    }
651	
652	    /**
653	     * Resolves the effective registration date for a create, rolled onto a business day. The
654	     * supplied date is used when present, otherwise the server's current date; either way the result
655	     * is rolled forward to the next Monday when it falls on a Saturday or Sunday (see
656	     * {@link BusinessDayAdjuster#toBusinessDay}). Every value derived from the registration date - the
657	     * stored {@code registrationDate}, the membership number's year segment and the daily
658	     * create-limit's per-day count - is judged on this adjusted date.
659	     *
660	     * @param suppliedRegistrationDate the registration date from the request, or {@code null} to
661	     *                                 default to the server's current date
662	     * @return the effective registration date, guaranteed to fall on a business day
663	     */
664	    /**
665	     * Rejects a create whose supplied {@code registrationDate} lies after the server's current date.
666	     * The raw submitted value is compared against {@link LocalDate#now()} before any business-day
667	     * adjustment; a future date cannot describe a registration that has already happened, so it is
668	     * reported as a {@code 400 Bad Request}. A {@code null} registration date (defaulted to the
669	     * server's current date) and any date on or before today are accepted.
670	     *
671	     * @param suppliedRegistrationDate the registration date from the request, or {@code null} when
672	     *                                 omitted
673	     * @throws InvalidOwnerFieldsException if the supplied date is later than the server's current date
674	     */
675	    private void rejectFutureRegistrationDate(LocalDate suppliedRegistrationDate) {
676	        if (suppliedRegistrationDate != null && suppliedRegistrationDate.isAfter(LocalDate.now())) {
677	            throw new InvalidOwnerFieldsException(List.of("registrationDate"));
678	        }
679	    }
680	
681	    private LocalDate effectiveRegistrationDate(LocalDate suppliedRegistrationDate) {
682	        LocalDate registrationDate =
683	            suppliedRegistrationDate != null ? suppliedRegistrationDate : LocalDate.now();
684	        return BusinessDayAdjuster.toBusinessDay(registrationDate);
685	    }
686	
687	    /**
688	     * Rejects creating an owner once {@link #MAX_OWNERS_PER_DAY} or more owners have already been
689	     * created for the given business day, judged by their stored {@code registrationDate}. Only owners
690	     * already persisted (before this create) are counted, and only those whose {@code registrationDate}
691	     * equals the adjusted registration date; a day at (or over) that limit is reported as a {@code 429
692	     * Too Many Requests}.
693	     *
694	     * @param registrationDate   the create's effective registration date, already rolled onto a
695	     *                           business day by {@link #effectiveRegistrationDate}
696	     * @param registeredThatDay  the number of owners already persisted (before this create) whose
697	     *                           {@code registrationDate} equals {@code registrationDate}
698	     * @throws OwnerDailyRegistrationLimitException if that day has already reached the maximum number of
699	     *                                              owner registrations
700	     */
701	    private void rejectDailyRegistrationLimitReached(LocalDate registrationDate, long registeredThatDay) {
702	        if (registeredThatDay >= MAX_OWNERS_PER_DAY) {
703	            throw new OwnerDailyRegistrationLimitException(registrationDate);
704	        }
705	    }
706	
707	    /**
708	     * Counts the owners already persisted (before this create) whose stored {@code registrationDate}
709	     * equals the given day. This is the shared per-day accumulation both the daily create-limit and the
710	     * bulk-signup warning are judged on.
711	     *
712	     * @param registrationDate the create's effective registration date, already rolled onto a business
713	     *                         day by {@link #effectiveRegistrationDate}
714	     * @return the number of existing owners registered on that day
715	     */
716	    private long countRegisteredOn(LocalDate registrationDate) {
717	        return this.clinicService.findAllOwners().stream()
718	            .map(Owner::getRegistrationDate)
719	            .filter(registrationDate::equals)
720	            .count();
721	    }
722	}
