41	     * and {@code QLD -> Australia/Brisbane}. Returns {@code null} for a region not in the table.
42	     */
43	    default String timezone(Owner owner) {
44	        String region = org.springframework.samples.petclinic.util.CustomerCode.region(owner.getCustomerCode());
45	        if (region == null) {
46	            return null;
47	        }
48	        return switch (region) {
49	            case "NSW" -> "Australia/Sydney";
50	            case "VIC" -> "Australia/Melbourne";
51	            case "QLD" -> "Australia/Brisbane";
52	            default -> null;
53	        };
54	    }
55	
56	    /**
57	     * Derives the owner's {@code ageBand} from its {@code birthDate}, measured against its
58	     * {@code registrationDate}: {@code MINOR} when under 18, {@code ADULT} from 18 to 64 and
59	     * {@code SENIOR} at 65 or older. Returns {@code null} when no birth date is present.
60	     */
61	    default OwnerDto.AgeBandEnum ageBand(Owner owner) {
62	        java.time.LocalDate birthDate = owner.getBirthDate();
63	        java.time.LocalDate asOf = owner.getRegistrationDate();
64	        if (birthDate == null || asOf == null) {
65	            return null;
66	        }
67	        int years = java.time.Period.between(birthDate, asOf).getYears();
68	        if (years < 18) {
69	            return OwnerDto.AgeBandEnum.MINOR;
70	        }
71	        if (years < 65) {
72	            return OwnerDto.AgeBandEnum.ADULT;
73	        }
74	        return OwnerDto.AgeBandEnum.SENIOR;
