107	    default int membershipLevel(Owner owner) {
108	        int points = membershipPoints(owner);
109	        if (points <= 1) {
110	            return 1;
111	        }
112	        if (points <= 3) {
113	            return 2;
114	        }
115	        if (points <= 5) {
116	            return 3;
117	        }
118	        return 4;
119	    }
120	
121	    /**
122	     * Composes the owner's {@code salutation} from its honorific {@code title} and {@code lastName}:
123	     * {@code title + ' ' + lastName} when a non-blank title is present, or just the {@code lastName}
124	     * when no title is given.
125	     */
126	    default String salutation(Owner owner) {
127	        String title = owner.getTitle();
128	        if (title == null || title.isBlank()) {
129	            return owner.getLastName();
130	        }
131	        return title + " " + owner.getLastName();
132	    }
