19	import java.util.Locale;
20	import java.util.Map;
21	
22	/**
23	 * Normalization of owner postal addresses. Kept separate from the owner controller and the
24	 * {@code Owner} model so the rule for shaping an address lives in one place, as pure functions with
25	 * no web or persistence dependencies. Mirrors {@link TelephoneNormalizer}, which does the same for
26	 * telephones.
27	 *
28	 * <p>A submitted address is reduced to its canonical form, which is the value stored and returned:
29	 * it is trimmed, every run of whitespace is collapsed to a single space, it is upper-cased, and
30	 * common street-type abbreviations are expanded to their full words ({@code ST -> STREET},
31	 * {@code RD -> ROAD}, {@code AVE -> AVENUE}). Expansion is applied per whole word, so an
32	 * abbreviation embedded in a longer word (e.g. the {@code ST} in {@code EAST}) is left untouched.
33	 */
34	public abstract class AddressNormalizer {
35	
36	    /** A run of one or more whitespace characters, collapsed to a single space. */
37	    private static final String WHITESPACE_RUN = "\\s+";
38	
39	    /** Whole-word (upper-case) abbreviations expanded to their full street type. */
40	    private static final Map<String, String> ABBREVIATIONS = Map.of(
41	        "ST", "STREET",
42	        "RD", "ROAD",
43	        "AVE", "AVENUE");
44	
45	    /**
46	     * Reduce a submitted address to its canonical form, which is the value to be stored and returned:
47	     * trimmed, every run of whitespace collapsed to a single space, upper-cased, and common street-type
48	     * abbreviations expanded ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}). An
49	     * address that is empty or whitespace-only reduces to the empty string.
50	     *
51	     * @param rawAddress the submitted address (non-null)
52	     * @return the canonical address
53	     */
54	    public static String normalize(String rawAddress) {
55	        String collapsed = rawAddress.trim().replaceAll(WHITESPACE_RUN, " ").toUpperCase(Locale.ROOT);
56	        if (collapsed.isEmpty()) {
57	            return collapsed;
58	        }
59	        String[] words = collapsed.split(" ");
60	        StringBuilder sb = new StringBuilder(collapsed.length());
61	        for (int i = 0; i < words.length; i++) {
62	            if (i > 0) {
63	                sb.append(' ');
64	            }
65	            sb.append(ABBREVIATIONS.getOrDefault(words[i], words[i]));
66	        }
67	        return sb.toString();
68	    }
69	
70	    /**
71	     * Reduce a submitted address to its canonical form exactly as {@link #normalize} does, but tolerate
72	     * an absent value: a {@code null} address is returned unchanged (still absent), so an optional
73	     * address field can be normalized in place without a separate presence check at every call site. A
74	     * blank value still reduces to the empty string.
75	     *
76	     * @param rawAddress the submitted address, or {@code null} when absent
77	     * @return the canonical address, or {@code null} when the input was {@code null}
78	     */
79	    public static String normalizeOrNull(String rawAddress) {
80	        return rawAddress == null ? null : normalize(rawAddress);
81	    }
82	
83	}
