24	/**
25	 * Comparison of owner households, an owner's {@code lastName} together with their {@code postcode}.
26	 * Kept separate from the owner controller and the {@code Owner} model so the rule for deciding when
27	 * two owners belong to the same household lives in one place, as pure functions with no web or
28	 * persistence dependencies. Mirrors {@link TelephoneNormalizer}, which does the same for telephones.
29	 *
30	 * <p>Two owners share a household when their {@linkplain #toComparisonKey(String, String) comparison
31	 * keys} are equal. The last name is reduced for comparison by trimming, collapsing every run of
32	 * whitespace to a single space and lower-casing, so households recorded in different letter cases or
33	 * with incidental spacing still compare equal (e.g. {@code "  Franklin "} / {@code "2000"} matches
34	 * {@code "franklin"} / {@code "2000"}); the postcode is a fixed 4-digit code and is compared as
35	 * given.
36	 */
37	public abstract class HouseholdNormalizer {
38	
39	    /** A run of one or more whitespace characters, collapsed to a single space for comparison. */
40	    private static final String WHITESPACE_RUN = "\\s+";
41	
42	    /** Separates the normalized {@code lastName} and {@code postcode} in a key. */
43	    private static final String KEY_SEPARATOR = "|";
44	
45	    /** The number of leading hex characters of the digest kept as the household id. */
46	    private static final int HOUSEHOLD_ID_LENGTH = 12;
47	
48	    /**
49	     * The key used to decide whether two owners belong to the same household: their normalized
50	     * {@code lastName} and {@code postcode} joined together, so households stored in different letter
51	     * cases or with incidental whitespace still compare equal.
52	     *
53	     * @param lastName the owner's last name (non-null)
54	     * @param postcode the owner's postcode, or null when absent
55	     * @return the comparison key
56	     */
57	    public static String toComparisonKey(String lastName, String postcode) {
58	        return normalizeField(lastName) + KEY_SEPARATOR + (postcode == null ? "" : postcode);
59	    }
60	
61	    /**
62	     * A stable, shared identifier for the household an owner belongs to. It is a pure function of the
63	     * {@linkplain #toComparisonKey(String, String) comparison key}, so every owner with the same
64	     * {@code lastName} (compared case-insensitively with collapsed whitespace) and {@code postcode}
65	     * derives the same identifier without any coordination or stored state, and the identifier stays
66	     * the same across restarts. The value is the first {@value #HOUSEHOLD_ID_LENGTH} hex characters
67	     * of the SHA-256 of the comparison key.
68	     *
69	     * @param lastName the owner's last name (non-null)
70	     * @param postcode the owner's postcode, or null when absent
71	     * @return the household's stable shared identifier
72	     */
73	    public static String toHouseholdId(String lastName, String postcode) {
74	        return sha256Hex(toComparisonKey(lastName, postcode)).substring(0, HOUSEHOLD_ID_LENGTH);
75	    }
76	
77	    /**
78	     * Reduce a single household field to its comparison form: trimmed, every run of whitespace
79	     * collapsed to a single space, and lower-cased.
80	     *
81	     * @param field a household field (non-null)
82	     * @return the field's comparison form
83	     */
84	    private static String normalizeField(String field) {
85	        return field.trim().replaceAll(WHITESPACE_RUN, " ").toLowerCase(Locale.ROOT);
86	    }
87	
88	    /** The lower-case hex SHA-256 of the UTF-8 bytes of {@code value}. */
89	    private static String sha256Hex(String value) {
90	        try {
91	            byte[] digest = MessageDigest.getInstance("SHA-256").digest(value.getBytes(StandardCharsets.UTF_8));
92	            StringBuilder sb = new StringBuilder(digest.length * 2);
93	            for (byte b : digest) {
94	                sb.append(Character.forDigit((b >> 4) & 0xF, 16));
95	                sb.append(Character.forDigit(b & 0xF, 16));
96	            }
97	            return sb.toString();
98	        }
99	        catch (NoSuchAlgorithmException ex) {
100	            // SHA-256 is a standard algorithm required to be present on every JVM.
101	            throw new IllegalStateException("SHA-256 not available", ex);
102	        }
103	    }
104	
105	}
